import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Swish: x * sigmoid(x)
__device__ float my_sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ float my_swish(float x) {
    return x * my_sigmoid(x);
}

// Tanh
__device__ float my_tanh(float x) {
    return tanhf(x);
}

// GELU (exact)
__device__ float my_gelu(float x) {
    // 0.5 * x * (1 + erf(x / sqrt(2)))
    return 0.5f * x * (1.0f + erff(x * 0.70710678118654752440f));
}

// Hardtanh clamp
__device__ float my_clamp(float x, float min_val, float max_val) {
    return fmaxf(min_val, fminf(x, max_val));
}

__global__ void fused_activation_kernel(const float* __restrict__ inp,
                                        const float* __restrict__ bias,
                                        float* __restrict__ out,
                                        int rows,
                                        int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = rows * cols;
    if (idx < size) {
        int col = idx % cols;

        float val = inp[idx] + bias[col];
        // Swish
        val = my_swish(val);
        // Tanh
        val = my_tanh(val);
        // GELU
        val = my_gelu(val);
        // Hardtanh clamp
        val = my_clamp(val, -1.0f, 1.0f);

        out[idx] = val;
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor x, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat, "x must be a float tensor");
    TORCH_CHECK(bias.dtype() == torch::kFloat, "bias must be a float tensor");

    int rows = x.size(0);
    int cols = x.size(1);
    auto out = torch::empty_like(x);

    const int block_size = 256;
    int size = rows * cols;
    int grid_size = (size + block_size - 1) / block_size;

    fused_activation_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(),
                                                       bias.data_ptr<float>(),
                                                       out.data_ptr<float>(),
                                                       rows,
                                                       cols);

    return out;
}
"""

fused_cpp_source = r"""
torch::Tensor fused_activation_cuda(torch::Tensor x, torch::Tensor bias);
"""

fused_module = load_inline(
    name="fused_activation",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_activation_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, add_value_shape):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.add_value = nn.Parameter(torch.randn(add_value_shape, device='cuda'))
        self.fused_activation = fused_module

    def forward(self, x):
        x = self.matmul(x)
        x = self.fused_activation.fused_activation_cuda(x, self.add_value)
        return x
